import{Ot as e,ct as t,it as n,lt as r,n as i,st as a,ut as o,wt as s}from"./chunks/framework.eUj94whv.js";var c=JSON.parse(`{"title":"阴影与材质","description":"","frontmatter":{},"headers":[],"relativePath":"design/shadow.md","filePath":"design/shadow.md","lastUpdated":1793226884000}`),l={name:`design/shadow.md`};function u(i,c,l,u,d,f){let p=e(`XhTokenTable`);return s(),a(`div`,null,[c[0]||=n(`h1`,{id:`阴影与材质`,tabindex:`-1`},[r(`阴影与材质 `),n(`a`,{class:`header-anchor`,href:`#阴影与材质`,"aria-label":`Permalink to “阴影与材质”`},`​`)],-1),c[1]||=n(`p`,null,`阴影在这里只表达"离页面多远"，不表达边界——边界归描边。阴影只有三档，按面的类型取，组件不自选：贴在页面上的 raised 取 sm，锚定浮层（floating 与 frosted）取 md，模态与强反馈面（sheet）取 lg。材质配方把底、边、影、高光与前景打包成四档，组件只挑档，不自己配光。`,-1),c[2]||=n(`h2`,{id:`海拔角色`,tabindex:`-1`},[r(`海拔角色 `),n(`a`,{class:`header-anchor`,href:`#海拔角色`,"aria-label":`Permalink to “海拔角色”`},`​`)],-1),o(p,{kind:`shadow`,names:[`--xh-elevation-raised`,`--xh-elevation-lifted`,`--xh-elevation-floating`,`--xh-elevation-sheet`],notes:{"--xh-elevation-raised":`贴在页面上、略抬起的面：Card、Tabs segment 的滑块、开关拇指。取 sm 档，边界仍由 border-default 描边承担，影只是加成`,"--xh-elevation-lifted":`被指针拎起来、正跟着手移动的东西：拖动中的排序项与字段组条目、悬停抬起的卡片。不另成一档，与 floating 同取 md`,"--xh-elevation-floating":`portal 出去的锚定浮层里含网格或多列的面板：日期 / 时间选择器面板、NavigationMenu 面板、侧栏弹出层。取 md 档`,"--xh-elevation-sheet":`模态与强反馈面：Dialog、Drawer、Command、Notification。取 lg 档`}}),c[3]||=t(`<p>浅色档的四个角色直接引原语：raised 引 <code>--xh-shadow-sm</code>，lifted 与 floating 引 <code>--xh-shadow-md</code>，sheet 引 <code>--xh-shadow-lg</code>。原语每档三层：贴边层画出面与底的交界、主层给出方向、环境层铺开大范围的暗，投影色取中性色阶最暗那一档的色相而不是纯黑。层级先靠描边与间距分，阴影只表达真实抬升。海拔逐部件登记（门禁 <code>check-elevation-role</code>），登记表之外的部件不许消费阴影。</p><h2 id="四档材质" tabindex="-1">四档材质 <a class="header-anchor" href="#四档材质" aria-label="Permalink to “四档材质”">​</a></h2><p>每档提供同名九项令牌：<code>bg</code>、<code>backdrop</code>、<code>border</code>、<code>highlight</code>、<code>shadow</code>、<code>separator</code>、<code>fg</code>、<code>fg-muted</code>、<code>focus-surface</code>。</p><table tabindex="0"><thead><tr><th>档</th><th>令牌</th><th>给谁</th><th>光学</th></tr></thead><tbody><tr><td>M0 solid</td><td><code>--xh-material-solid-*</code></td><td>静态内容面缺省：border-default 描边 + surface 底 + 无影；字段静息同为描边式，铺 <code>--xh-bg-field</code>（缺省白底）</td><td>实体底色，无高光、无投影</td></tr><tr><td>M1 soft</td><td><code>--xh-material-soft-*</code></td><td>柔和淡底的次级面；不用于 Card 与字段。Button 与 Tag 是平面面，不取它的顶光与投影</td><td>实体底色，细微顶光与两段接触投影，无背景模糊</td></tr><tr><td>M2 frosted</td><td><code>--xh-material-frosted-*</code></td><td>短列表、菜单、tooltip、气泡等锚定瞬态浮层</td><td>实体 surface 底，无背景模糊，1px border-default 描边，md 档投影，无顶光</td></tr><tr><td>M4 elevated</td><td><code>--xh-material-elevated-*</code></td><td>Dialog、Drawer、Command、Tour、Notification 等模态与强反馈面，必有 1px 描边</td><td>实体 surface 底，无背景模糊，lg 档投影</td></tr></tbody></table><p>另有两个由海拔组成的叠加档：raised = solid 描边 + solid 底 + <code>--xh-elevation-raised</code>（Card 与可抬起 / 可拖起部件）；floating = solid 底 + <code>--xh-border-default</code> + <code>--xh-elevation-floating</code>（含网格或多列的锚定面板）。它们没有 <code>--xh-material-*</code> 令牌。</p><h2 id="frosted-浮层面" tabindex="-1">frosted 浮层面 <a class="header-anchor" href="#frosted-浮层面" aria-label="Permalink to “frosted 浮层面”">​</a></h2><ul><li>名字沿用 frosted，取值是实体弹出层：<code>--xh-bg-surface</code> 不透明底、1px <code>--xh-border-default</code> 描边、md 档投影（浅色引 <code>--xh-shadow-md</code>，深色是同样三层的深色投影），不采样背后内容，没有顶部边界光。</li><li>只用于锚定瞬态浮层（短列表、菜单、气泡、提示框）；正文、表单主体、Card、Table、Notification 与 Dialog 主阅读面不用。</li><li>必须有 1px 可见边界，不能只靠投影分层。</li><li>含网格或多列的锚定面板（日期面板、多列级联）用 floating：实体底 + border-default + <code>--xh-elevation-floating</code>。</li><li>背景滤镜与顶光两条通道保留给主题：要磨砂透景时，给 <code>--xh-material-frosted-bg</code> 半透明底、给 backdrop 一档 blur（不高于 16px，saturate 不高于 1.08）、给 highlight 不超过 1px 的内侧顶光；减少透明度、强制色与打印下这些通道一律退回实体面。开了透景的主题不把 <code>backdrop-filter</code> 放在页面根、大滚动区或重叠的多层表面，不对模糊半径做动画。</li><li>没有 glass 材质，也没有任何兼容别名。</li></ul><p>Tooltip 不反白，与 Popover 同一副浮层面：底、字、边取 frosted 材质，再用三支 compact 配方（<code>--xh-material-frosted-compact-alpha / -backdrop / -shadow</code>，缺省不透明、无模糊、md 档投影）组合；写了 <code>tone</code> 才换语气实底，边改取 on 色 20% 拼色承担 1px 可见边界。</p><h2 id="深色档的投影" tabindex="-1">深色档的投影 <a class="header-anchor" href="#深色档的投影" aria-label="Permalink to “深色档的投影”">​</a></h2><p>深色主题的投影色留在纯黑：中性色阶最暗的一档比页面底还亮，拿它当投影压不出深度。四个海拔角色在深色档是多层投影，末尾带一条 1px 的浅色描边把面的上沿提出来——raised 与 lifted 那条写成 inset 且只画上边缘，不绕四周，否则会与输入框壳这类自带描边的面并成相距 1px 的两道线。frosted 与 elevated 两档材质在深色档分别取 floating 与 sheet 同样的三层深色投影，不带末尾那条浅色描边（材质自己有 1px 描边）。</p><h2 id="环境轴上的降级" tabindex="-1">环境轴上的降级 <a class="header-anchor" href="#环境轴上的降级" aria-label="Permalink to “环境轴上的降级”">​</a></h2><p>同一令牌名原位降级：高对比档加强边界；减少透明度（<code>data-transparency=&quot;reduce&quot;</code>）与打印强制实体底、关闭背景滤镜（主题开了透景也一样）；打印另把四档海拔置 none；强制色改由 <code>Canvas</code> / <code>CanvasText</code> 表达。四档在浅色、深色两套主题下都按黑、白、中灰、页面与品牌背景验证正文至少 4.5:1、焦点环对隔离底至少 3:1。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to “相关”">​</a></h2><ul><li><a href="/design/shape">形状与边界</a> · <a href="/design/dark">暗黑模式</a></li><li>指南：<a href="/guide/theme#材质配方">设计令牌与主题 · 材质配方</a></li></ul>`,14)])}var d=i(l,[[`render`,u]]);export{c as __pageData,d as default};